// SoC Explorer (v1.32): one small RISC-V system-on-chip read four ways (RTL, gates, layout, state
// machine) with a shared selection. Netlists, placements and RTL come from data/soc.json (generated by
// sim/transistor_sim/soc.py); the core, pipeline, x86 translator, gate evaluation and timing run in
// the browser through physics/riscv.js, the twin of sim/transistor_sim/physics/riscv.py.
import { SOC, SOCCELLS, REFS } from './data.js';
import * as RV from '../physics/riscv.js';

const $ = (s, r = document) => r.querySelector(s);
const NS = 'http://www.w3.org/2000/svg';
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const reduce = () => matchMedia('(prefers-reduced-motion: reduce)').matches;
const store = {
  get(k, d) { try { const v = localStorage.getItem(k); return v === null ? d : JSON.parse(v); } catch { return d; } },
  set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch { /* private mode */ } },
};
const hex = (v, n = 8) => '0x' + (v >>> 0).toString(16).padStart(n, '0');
const CELLNAME = { inv: 'inverter', nand2: 'NAND2', nand3: 'NAND3', nor2: 'NOR2', nor3: 'NOR3', aoi21: 'AOI21', oai21: 'OAI21', aoi22: 'AOI22', xor2: 'XOR2' };
const TECHLABEL = { planar_180: '180 nm planar', finfet_5: '5 nm FinFET', gaa_2: '2 nm nanosheet' };
const STATE_TXT = {
  FETCH: 'Read the instruction at PC from memory into IR, and add 4 to PC.',
  DECODE: 'Read the two source registers and work out the instruction class; the ALU computes the branch target.',
  EXEC_R: 'The ALU combines two registers.', EXEC_I: 'The ALU combines a register and the immediate.',
  MEMADR: 'The ALU adds the offset to the base register: the memory address.', BRANCH: 'The ALU compares the two registers; if the branch is taken, PC jumps.',
  JAL: 'Save PC + 4 in rd and jump.', LUI: 'Write the 20-bit immediate, shifted left 12, into rd.',
  ALUWB: 'Write the ALU result into rd.', MEMRD: 'Read the data word from memory.', MEMWR: 'Write the register to memory (RAM or the LEDs).', MEMWB: 'Write the loaded word into rd.',
};

const state = {
  mod: store.get('soc:mod', 'ctrl'), tech: store.get('soc:tech', 'finfet_5'), rtl: 'mod', crit: false, live: true,
  sel: null, step: 0, alu: { a: 6, b: 3, op: 'add' }, follow: true,
  src: SOC.demo, words: [], lines: [], trace: [], final: null, cur: 0, timer: null,
};
if (!SOC.techs[state.tech]) state.tech = 'finfet_5';
if (!SOC.modules[state.mod]) state.mod = 'ctrl';
const mod = () => SOC.modules[state.mod];
const gateById = () => Object.fromEntries(mod().netlist.cells.map((g) => [g.id, g]));

// ------------------------------------------------------------------ the core run
function assembleAndReset(src) {
  const a = RV.assemble(src);
  const mc = RV.multicycle(a.words);
  state.src = src; state.words = a.words; state.lines = a.lines;
  state.trace = mc.trace; state.final = mc; state.cur = 0;
  state.srcLines = src.split(/\r?\n/);
}
const atEnd = () => state.cur >= state.trace.length;
const cyc = () => state.trace[Math.min(state.cur, state.trace.length - 1)];

function coreInputs() {
  const t = cyc();
  const d = RV.decode(state.words[t.idx]);
  const s = RV.STATES.indexOf(t.state), c = d.code;
  const v = {};
  for (let b = 0; b < 4; b++) v[`s${b}`] = (s >> b) & 1;
  for (let b = 0; b < 3; b++) v[`c${b}`] = (c >> b) & 1;
  return { v, d, t };
}

// ALU operands the core uses in this cycle (low 4 bits), when it uses the ALU at all
function coreAlu() {
  const { d, t } = coreInputs();
  const x = t.x, A = x[d.rs1], B = ['R', 'BRANCH'].includes(d.cls) ? x[d.rs2] : d.imm;
  const use = SOC.modules.alu.use[t.state];
  if (!use) return null;
  let op = 'add';
  if (t.state === 'BRANCH' || d.op === 'sub') op = 'sub';
  else if (d.op === 'and' || d.op === 'andi') op = 'and';
  else if (d.op === 'or' || d.op === 'ori') op = 'or';
  if (t.state === 'DECODE' || t.state === 'JAL') return { a: t.pc & 15, b: d.imm & 15, op: 'add', why: 'PC + immediate (branch or jump target)' };
  if (t.state === 'MEMADR') return { a: A & 15, b: d.imm & 15, op: 'add', why: 'base + offset (memory address)' };
  return { a: A & 15, b: B & 15, op, why: `${d.text}` };
}

// ------------------------------------------------------------------ chip / datapath diagram
const BLOCKS = {
  pcadd: [30, 50, 60, 36, '+4'], pc: [30, 150, 60, 44, 'PC'], ir: [120, 150, 64, 44, 'IR'],
  ctrl: [120, 34, 140, 62, 'Controller'], imm: [214, 262, 80, 36, 'Imm gen'], rf: [214, 126, 96, 96, 'Registers'],
  alu: [344, 130, 74, 88, 'ALU'], aluout: [444, 150, 64, 44, 'ALUOut'], mdr: [444, 262, 64, 36, 'MDR'],
  mem: [588, 40, 152, 120, 'RAM 4 KiB'], gpio: [588, 210, 152, 110, 'GPIO'],
};
const WIRES = [['pcadd', 'pc'], ['pc', 'mem'], ['aluout', 'mem'], ['mem', 'ir'], ['mem', 'mdr'], ['ir', 'rf'], ['ir', 'imm'], ['ir', 'ctrl'],
  ['rf', 'alu'], ['imm', 'alu'], ['alu', 'aluout'], ['aluout', 'rf'], ['mdr', 'rf'], ['alu', 'pc'], ['imm', 'rf'], ['pc', 'alu']];
const ctr = (b) => [BLOCKS[b][0] + BLOCKS[b][2] / 2, BLOCKS[b][1] + BLOCKS[b][3] / 2];

function drawChip() {
  const svg = $('#socDp');
  let h = '<defs><marker id="dpArr" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="currentColor"/></marker></defs>';
  h += '<rect class="dp-core" x="12" y="12" width="512" height="334" rx="14"/><text class="dp-cap" x="26" y="334">RV32I core · multi-cycle</text>';
  h += '<rect class="dp-bus" x="546" y="30" width="18" height="300" rx="4" data-b="bus"/><text class="dp-cap" x="555" y="345" text-anchor="middle">bus</text>';
  for (const [a, b] of WIRES) {
    const [x1, y1] = ctr(a), [x2, y2] = ctr(b);
    const viaBus = a === 'mem' || b === 'mem';
    const d = viaBus ? `M${x1},${y1} L555,${y1} L555,${y2} L${x2},${y2}` : `M${x1},${y1} L${x2},${y2}`;
    h += `<path class="dp-w" data-w="${a}-${b}" d="${d}"/>`;
  }
  for (const [id, [x, y, w, hh, lab]] of Object.entries(BLOCKS)) {
    const clickable = id === 'alu' || id === 'ctrl' || id === 'mem';
    h += `<g class="dp-b${clickable ? ' dp-link' : ''}" data-b="${id}"${clickable ? ` tabindex="0" role="button" aria-label="${lab}: open ${id === 'mem' ? 'the 6T SRAM cell on the Gate to silicon bench' : 'its gates and layout'}"` : ''}><rect x="${x}" y="${y}" width="${w}" height="${hh}" rx="8"/><text x="${x + w / 2}" y="${y + 18}" text-anchor="middle">${lab}</text>`;
    if (id === 'ctrl') h += `<text class="dp-state" id="dpState" x="${x + w / 2}" y="${y + 42}" text-anchor="middle"></text>`;
    if (id === 'alu') h += `<text class="dp-val" id="dpAlu" x="${x + w / 2}" y="${y + 50}" text-anchor="middle"></text>`;
    if (id === 'mem') h += `<text class="dp-sub" x="${x + w / 2}" y="${y + 40}" text-anchor="middle">6T SRAM bitcells</text><text class="dp-val" id="dpMem" x="${x + w / 2}" y="${y + 70}" text-anchor="middle"></text>`;
    if (id === 'gpio') {
      h += `<text class="dp-sub" x="${x + w / 2}" y="${y + 36}" text-anchor="middle">at 0x1000_0000</text>`;
      for (let i = 0; i < 8; i++) h += `<circle class="led" id="led${7 - i}" cx="${x + 20 + i * 16}" cy="${y + 66}" r="6"/>`;
      h += `<text class="dp-val" id="dpGpio" x="${x + w / 2}" y="${y + 96}" text-anchor="middle"></text>`;
    }
    h += '</g>';
  }
  h += '<text class="dp-ctl" id="dpCtl" x="26" y="312"></text>';
  svg.innerHTML = h;
  svg.querySelectorAll('.dp-link').forEach((g) => {
    const go = () => {
      const b = g.dataset.b;
      if (b === 'mem') { location.href = 'fab.html#gates'; return; }
      setMod(b === 'alu' ? 'alu' : 'ctrl');
      $('#views').scrollIntoView({ behavior: reduce() ? 'auto' : 'smooth' });
    };
    g.addEventListener('click', go);
    g.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); go(); } });
  });
}

function renderChip() {
  const done = atEnd();
  const t = cyc();
  const busy = new Set(done ? [] : t.busy);
  if (busy.has('mem')) busy.add('bus');
  document.querySelectorAll('#socDp .dp-b').forEach((g) => g.classList.toggle('on', busy.has(g.dataset.b)));
  $('#socDp .dp-bus').classList.toggle('on', busy.has('bus'));
  document.querySelectorAll('#socDp .dp-w').forEach((p) => { const [a, b] = p.dataset.w.split('-'); p.classList.toggle('on', busy.has(a) && busy.has(b)); });
  const x = done ? state.final.x : t.x, gpio = done ? state.final.gpio : t.gpio;
  $('#dpState').textContent = done ? 'halted' : t.state;
  $('#dpCtl').textContent = done ? '' : (t.ctrl.length ? 'asserted: ' + t.ctrl.join(' · ') : 'no write signals this cycle');
  const ca = done ? null : coreAlu();
  $('#dpAlu').textContent = ca ? `${ca.op}` : '';
  for (let i = 0; i < 8; i++) $(`#led${i}`).classList.toggle('on', ((gpio >> i) & 1) === 1);
  $('#dpGpio').textContent = `LEDs = ${gpio} = 0b${gpio.toString(2).padStart(8, '0')}`;
  const mem = done ? state.final.mem : null;
  $('#dpMem').textContent = mem && Object.keys(mem).length ? Object.entries(mem).map(([k, v]) => `[${hex(+k, 3)}] = ${v}`).join('  ') : '';
  // program listing
  document.querySelectorAll('#socList li').forEach((li, i) => li.classList.toggle('cur', !done && i === t.idx));
  // registers
  $('#socRegs').innerHTML = x.map((v, i) => `<span class="${!done && state.cur > 0 && state.trace[state.cur - 1].x[i] !== v ? 'chg' : ''}"><b>x${i}</b>${(v | 0)}</span>`).join('');
  const st = $('#socStatus');
  st.textContent = done
    ? `Halted after ${state.final.cycles} cycles and ${state.final.retired} instructions: ${state.final.cpi.toFixed(2)} cycles per instruction.`
    : `Cycle ${t.cycle} · ${t.state}: ${STATE_TXT[t.state]} · ${t.text}`;
  renderLive();
  renderFsmLive();
}

function stepCycle() { if (!atEnd()) state.cur++; renderChip(); }
function stepInstr() {
  if (atEnd()) return renderChip();
  do { state.cur++; } while (!atEnd() && state.trace[state.cur].state !== 'FETCH');
  renderChip();
}
function run(on) {
  clearInterval(state.timer); state.timer = null;
  $('#socRun').setAttribute('aria-pressed', String(on));
  $('#socRun').textContent = on ? 'Pause' : 'Run';
  if (!on) return;
  state.timer = setInterval(() => { if (atEnd()) return run(false); stepCycle(); }, reduce() ? 600 : 260);
}

function renderList() {
  $('#socList').innerHTML = state.words.map((w, i) => {
    const d = RV.decode(w);
    const src = (state.srcLines[state.lines[i] - 1] || '').split('#')[0].trim();
    return `<li><span class="ad">${hex(4 * i, 2)}</span><code class="wd">${hex(w)}</code><span class="tx">${esc(src || d.text)}</span></li>`;
  }).join('');
}

// ------------------------------------------------------------------ selection model
function resolve() {
  const out = { gates: new Set(), lines: new Set(), edges: new Set(), states: new Set(), blocks: new Set(), text: '' };
  const s = state.sel;
  if (!s) return out;
  const m = mod(), G = gateById(), rtl = rtlLines();
  const isCtrl = state.mod === 'ctrl';
  const linesWith = (pred) => rtl.forEach((l, i) => { if (l.tags.some(pred)) out.lines.add(i); });
  const aluUse = (S) => new Set(m.use?.[S] || []);
  if (s.k === 'gate') {
    const g = G[s.id];
    if (!g) return out;
    out.gates.add(g.id);
    if (isCtrl) {
      (g.edges || []).forEach((e) => out.edges.add(e));
      (g.states || []).forEach((S) => out.states.add(S));
      linesWith((t) => (t.startsWith('edge:') && out.edges.has(t.slice(5))) || (t.startsWith('state:') && out.states.has(t.slice(6))) || g.tags.includes(t));
      const term = g.tags.find((t) => t.startsWith('term:')), outp = g.tags.filter((t) => t.startsWith('out:')).map((t) => t.slice(4));
      out.text = `${CELLNAME[g.cell]} ${g.id}` + (term ? ` builds the product term ${term.slice(5)}` : '') + (outp.length ? ` · part of ${outp.join(', ')}` : '') +
        (out.edges.size ? ` · used by ${out.edges.size} transition${out.edges.size > 1 ? 's' : ''}` : '') + (out.states.size ? ` · asserts outputs in ${[...out.states].join(', ')}` : '');
    } else {
      const tags = g.tags.filter((t) => !t.startsWith('bit'));
      linesWith((t) => tags.includes(t));
      Object.keys(m.use).forEach((S) => { if (tags.some((t) => aluUse(S).has(t))) out.states.add(S); });
      const bit = g.tags.find((t) => t.startsWith('bit'));
      out.text = `${CELLNAME[g.cell]} ${g.id}${bit ? ` in ${bit.replace('bit', 'bit ')}` : ''} · role: ${tags.join(', ')} · ${EFFORT_TXT(g)}`;
    }
  } else if (s.k === 'line') {
    const l = rtl[s.i];
    out.lines.add(s.i);
    if (state.rtl !== 'mod') {
      l.tags.filter((t) => t.startsWith('dp:') || t.startsWith('soc:')).forEach((t) => out.blocks.add(t.split(':')[1]));
      out.text = `Line ${s.i + 1}: ${l.t.trim()}` + (out.blocks.size ? ` · blocks: ${[...out.blocks].join(', ')}` : '');
    } else if (isCtrl) {
      for (const t of l.tags) {
        if (t.startsWith('edge:')) { out.edges.add(t.slice(5)); (m.view[t.slice(5)] || []).forEach((id) => out.gates.add(id)); }
        if (t.startsWith('state:')) { out.states.add(t.slice(6)); (m.view[t.slice(6)] || []).forEach((id) => out.gates.add(id)); }
        if (t.startsWith('out:')) m.netlist.cells.forEach((g) => { if (g.tags.includes(t)) out.gates.add(g.id); });
        if (t === 'outs') m.netlist.cells.forEach((g) => { if (g.tags.some((x) => x.startsWith('out:') && SOC.controls.includes(x.slice(4)))) out.gates.add(g.id); });
        if (t === 'in') m.netlist.cells.forEach((g) => { if (g.tags.includes('inputs')) out.gates.add(g.id); });
      }
      out.text = `Line ${s.i + 1}: ${l.t.trim()} → ${out.gates.size} gate${out.gates.size === 1 ? '' : 's'}` + (l.tags.includes('reg') ? ' (the state register itself is four flip-flops, not drawn)' : '');
    } else {
      m.netlist.cells.forEach((g) => { if (g.tags.some((t) => l.tags.includes(t))) out.gates.add(g.id); });
      out.text = `Line ${s.i + 1}: ${l.t.trim()} → ${out.gates.size} gate${out.gates.size === 1 ? '' : 's'}`;
    }
  } else if (s.k === 'edge' || s.k === 'state') {
    const key = s.k === 'edge' ? s.e : s.s;
    if (s.k === 'edge') out.edges.add(key); else out.states.add(key);
    const [from, cond, to] = s.k === 'edge' ? key.split('>') : [key, '', ''];
    if (isCtrl) {
      (m.view[key] || []).forEach((id) => out.gates.add(id));
      linesWith((t) => t === (s.k === 'edge' ? `edge:${key}` : `state:${key}`));
      out.text = s.k === 'edge'
        ? `${from} → ${to}${cond ? ` when the class is ${cond}` : ''}: ` + (out.gates.size ? `${out.gates.size} gates raise the next-state bits that are 1 in ${to} (code ${RV.STATES.indexOf(to).toString(2).padStart(4, '0')})` : `${to} is code 0000, so no product term fires: every next-state bit simply stays 0`)
        : `${key}: ${STATE_TXT[key]} ` + (out.gates.size ? `Its outputs (${(SOC.asserts[key] || []).join(', ')}) come from ${out.gates.size} gates.` : 'It asserts none of the six write signals.');
    } else {
      const S = s.k === 'edge' ? to : key;
      const use = aluUse(S);
      m.netlist.cells.forEach((g) => { if (g.tags.some((t) => use.has(t))) out.gates.add(g.id); });
      linesWith((t) => use.has(t));
      out.states.add(S);
      out.text = use.size ? `In ${S} the ALU is used for: ${[...use].join(', ')} → ${out.gates.size} of its ${m.netlist.cells.length} gates` : `${S} does not use the ALU.`;
    }
  } else if (s.k === 'net') {
    m.netlist.cells.forEach((g) => { if (g.out === s.n || Object.values(g.ins).includes(s.n)) out.gates.add(g.id); });
    out.text = `Net ${s.n}: driven by ${m.netlist.inputs.includes(s.n) ? 'an input pin' : [...out.gates].find((id) => G[id].out === s.n)}, ${[...out.gates].filter((id) => G[id].out !== s.n).length} loads`;
  }
  return out;
}
const EFFORT_TXT = (g) => { const e = SOC.effort[g.cell]; return `logical effort g = ${Object.values(e.g).map((v) => v.toFixed(2)).join('/')}, parasitic p = ${e.p.toFixed(2)}, ${e.n} transistors`; };

function select(s) {
  state.sel = s && state.sel && JSON.stringify(s) === JSON.stringify(state.sel) ? null : s;
  applySel();
}

function applySel() {
  const r = resolve();
  const any = !!state.sel;
  const crit = new Set(state.crit ? mod().sta.path : []);
  document.querySelectorAll('#socGates .g').forEach((el) => {
    el.classList.toggle('sel', r.gates.has(el.dataset.id));
    el.classList.toggle('dim', any && !r.gates.has(el.dataset.id));
    el.classList.toggle('crit', crit.has(el.dataset.id));
  });
  document.querySelectorAll('#socGates .w').forEach((el) => {
    const hit = r.gates.has(el.dataset.to) || r.gates.has(el.dataset.from) || (state.sel?.k === 'net' && el.dataset.n === state.sel.n);
    el.classList.toggle('sel', hit && any);
    el.classList.toggle('dim', any && !hit);
    el.classList.toggle('crit', crit.has(el.dataset.to) && (crit.has(el.dataset.from) || !el.dataset.from));
  });
  document.querySelectorAll('#socLayout .lc').forEach((el) => {
    el.classList.toggle('sel', r.gates.has(el.dataset.id));
    el.classList.toggle('crit', crit.has(el.dataset.id));
  });
  $('#socLayout')?.classList.toggle('has-sel', any && r.gates.size > 0);
  document.querySelectorAll('#socRtl .ln').forEach((el, i) => el.classList.toggle('sel', r.lines.has(i)));
  document.querySelectorAll('#socFsm .st').forEach((el) => el.classList.toggle('sel', r.states.has(el.dataset.s)));
  document.querySelectorAll('#socFsm .ed').forEach((el) => el.classList.toggle('sel', r.edges.has(el.dataset.e)));
  document.querySelectorAll('#socDp .dp-b').forEach((el) => el.classList.toggle('sel', r.blocks.has(el.dataset.b)));
  $('#socSel').textContent = any ? r.text : 'Nothing selected. Click a line, a gate, a cell or a state.';
  const first = document.querySelector('#socRtl .ln.sel');
  if (first && state.sel?.k !== 'line') { const box = $('#socRtl'); box.scrollTop = Math.max(0, first.offsetTop - box.clientHeight / 3); }
}

// ------------------------------------------------------------------ RTL view
function rtlLines() { return state.rtl === 'mod' ? mod().rtl : state.rtl === 'core' ? SOC.core_rtl : SOC.soc_rtl; }
const KW = /\b(module|endmodule|input|output|reg|wire|assign|always|begin|end|if|else|case|endcase|localparam|posedge)\b/g;
function hl(t) {
  const [code, ...cm] = t.split('//');
  let h = esc(code).replace(KW, '<i class="kw">$1</i>').replace(/\b(\d+'[bhd][0-9a-fA-F_]+|\d+)\b/g, '<i class="nm">$1</i>');
  if (cm.length) h += `<i class="cm">//${esc(cm.join('//'))}</i>`;
  return h;
}
function renderRtl() {
  $('#socRtlTab').innerHTML = [['mod', state.mod === 'ctrl' ? 'control.v' : 'alu4.v'], ['core', 'core.v'], ['soc', 'soc.v']]
    .map(([k, l]) => `<button type="button" data-v="${k}" aria-pressed="${state.rtl === k}">${l}</button>`).join('');
  $('#socRtl').innerHTML = rtlLines().map((l, i) => `<span class="ln${l.tags.length ? ' tg' : ''}" data-i="${i}"${l.tags.length ? ' tabindex="0" role="button"' : ''}><span class="no" aria-hidden="true">${i + 1}</span>${hl(l.t) || ' '}</span>`).join('');
}

// ------------------------------------------------------------------ gate schematic
const SYM = {
  inv: { body: 'M-12,-11 L10,0 L-12,11 Z', bub: 13, out: 16 },
  nand2: { body: 'M-16,-13 H0 A13,13 0 0 1 0,13 H-16 Z', bub: 16, out: 19 },
  nand3: { body: 'M-16,-15 H-1 A15,15 0 0 1 -1,15 H-16 Z', bub: 17, out: 20 },
  nor2: { body: 'M-16,-13 Q-8,0 -16,13 Q6,13 16,0 Q6,-13 -16,-13 Z', bub: 19, out: 22 },
  nor3: { body: 'M-16,-15 Q-7,0 -16,15 Q6,15 16,0 Q6,-15 -16,-15 Z', bub: 19, out: 22 },
  xor2: { body: 'M-13,-13 Q-5,0 -13,13 Q8,13 18,0 Q8,-13 -13,-13 Z M-18,-13 Q-10,0 -18,13', bub: null, out: 18 },
  aoi22: { body: 'M-16,-17 H10 Q16,-17 16,-11 V11 Q16,17 10,17 H-16 Z', bub: 19, out: 22, lab: 'AOI22' },
  aoi21: { body: 'M-16,-15 H10 Q16,-15 16,-9 V9 Q16,15 10,15 H-16 Z', bub: 19, out: 22, lab: 'AOI21' },
  oai21: { body: 'M-16,-15 H10 Q16,-15 16,-9 V9 Q16,15 10,15 H-16 Z', bub: 19, out: 22, lab: 'OAI21' },
};
const COLW = 104, ROWH = 40, PADX = 70, PADY = 26;
let geo = null;

function layoutGates() {
  const nl = mod().netlist;
  const lvl = {}, drv = {};
  nl.inputs.forEach((n) => { lvl[n] = 0; });
  nl.cells.forEach((g) => { lvl[g.out] = 1 + Math.max(...Object.values(g.ins).map((n) => lvl[n])); drv[g.out] = g; });
  const cols = [];
  nl.cells.forEach((g) => { const L = lvl[g.out]; (cols[L] ||= []).push(g); });
  const y = {};
  nl.inputs.forEach((n, i) => { y[n] = i; });
  // barycentre ordering: each column sorted by the mean row of its drivers
  for (let L = 1; L < cols.length; L++) {
    if (!cols[L]) { cols[L] = []; continue; }
    cols[L].sort((a, b) => {
      const m = (g) => { const v = Object.values(g.ins).map((n) => y[n]); return v.reduce((p, q) => p + q, 0) / v.length; };
      return m(a) - m(b) || (a.id < b.id ? -1 : 1);
    });
    const used = new Set();
    cols[L].forEach((g) => {
      const v = Object.values(g.ins).map((n) => y[n]);
      const want = Math.round(v.reduce((p, q) => p + q, 0) / v.length);
      let r = want;
      for (let k = 0; !(r >= 0 && !used.has(r)); k++) r = want + (k % 2 ? -(k + 1) / 2 : k / 2 + 1);  // nearest free row
      used.add(r); y[g.out] = r;
    });
  }
  const rows = Math.max(nl.inputs.length, ...Object.values(y)) + 1;
  const pos = {};
  nl.inputs.forEach((n) => { pos[n] = [PADX - 18, PADY + y[n] * ROWH]; });
  nl.cells.forEach((g) => { pos[g.id] = [PADX + (lvl[g.out] - 0.5) * COLW, PADY + y[g.out] * ROWH]; });
  const outs = [...nl.outputs].sort((a, b) => y[a] - y[b] || (a < b ? -1 : 1));
  const oy = {};
  const step = Math.max(1, Math.min(2, (rows - 1) / Math.max(1, outs.length - 1)));
  outs.forEach((n, i) => { oy[n] = PADY + Math.round(i * step * ROWH * 10) / 10; });
  const W = PADX + cols.length * COLW + 110, H = PADY * 2 + Math.max(rows, outs.length * step) * ROWH;
  return { lvl, pos, W, H, drv, nl, oy };
}

function pinY(g, pin) {
  const pins = SOCCELLS.gates[g.cell].inputs, k = pins.indexOf(pin), n = pins.length;
  const span = n === 4 ? 24 : n === 3 ? 20 : n === 2 ? 14 : 0;
  return n === 1 ? 0 : -span / 2 + (span * k) / (n - 1);
}
function outXY(n) {
  const g = geo.drv[n];
  if (!g) return geo.pos[n];
  const [x, y] = geo.pos[g.id];
  return [x + SYM[g.cell].out, y];
}

function renderGates() {
  geo = layoutGates();
  const { nl, pos, W, H } = geo;
  const svg = $('#socGates');
  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  svg.setAttribute('width', W); svg.setAttribute('height', H);
  let w = '', g = '';
  nl.cells.forEach((c) => {
    const [x, y] = pos[c.id];
    Object.entries(c.ins).forEach(([pin, n]) => {
      const [x1, y1] = outXY(n), x2 = x - 16, y2 = y + pinY(c, pin);
      const xm = Math.max(x1 + 10, x2 - 18);
      const from = geo.drv[n]?.id || '';
      w += `<path class="w" data-n="${n}" data-from="${from}" data-to="${c.id}" d="M${x1},${y1} C${xm},${y1} ${xm},${y2} ${x2},${y2}"/>`;
    });
    const s = SYM[c.cell];
    g += `<g class="g" data-id="${c.id}" tabindex="0" role="button" aria-label="${CELLNAME[c.cell]} ${c.id}" transform="translate(${x},${y})"><title>${CELLNAME[c.cell]} ${c.id} → ${c.out}</title><path class="gb" d="${s.body}"/>` +
      (s.bub ? `<circle class="gb" cx="${s.bub}" cy="0" r="3"/>` : '') + (s.lab ? `<text class="gl" x="-1" y="3" text-anchor="middle">${s.lab}</text>` : '') + '</g>';
  });
  let io = '';
  nl.inputs.forEach((n) => { const [x, y] = pos[n]; io += `<g class="pi" data-n="${n}"><text x="${x - 6}" y="${y + 4}" text-anchor="end">${n}</text><circle cx="${x}" cy="${y}" r="2.5"/></g>`; });
  nl.outputs.forEach((n) => {
    const [x1, y1] = outXY(n), x2 = W - 86, y2 = geo.oy[n], xm = Math.max(x1 + 20, x2 - 40);
    w += `<path class="w po" data-n="${n}" data-from="${geo.drv[n].id}" data-to="" d="M${x1},${y1} C${xm},${y1} ${xm},${y2} ${x2},${y2}"/>`;
    io += `<text class="po-t" x="${x2 + 6}" y="${y2 + 4}">${n}</text>`;
  });
  svg.innerHTML = `<g class="wires">${w}</g>${io}${g}`;
  const st = mod().stats;
  $('#socGateMeta').textContent = `${st.cells} cells · ${st.transistors} transistors · depth ${Math.max(...Object.values(geo.lvl))}`;
  renderAluIn();
  renderLive();
  applySel();
}

function liveInputs() {
  if (state.mod === 'ctrl') return atEnd() ? null : coreInputs().v;
  let { a, b, op } = state.alu;
  if (state.follow && !atEnd()) { const c = coreAlu(); if (c) ({ a, b, op } = c); }
  const v = { sub: op === 'sub' ? 1 : 0, f1: op === 'add' || op === 'sub' ? 1 : 0, f0: op === 'or' ? 1 : 0 };
  for (let i = 0; i < 4; i++) { v[`a${i}`] = (a >> i) & 1; v[`b${i}`] = (b >> i) & 1; }
  return v;
}
function renderLive() {
  const svg = $('#socGates');
  if (!svg || !geo) return;
  const vin = state.live ? liveInputs() : null;
  svg.classList.toggle('live', !!vin);
  if (!vin) return;
  const v = RV.evalNetlist(mod().netlist, vin);
  svg.querySelectorAll('.w').forEach((p) => p.classList.toggle('hi', v[p.dataset.n] === 1));
  svg.querySelectorAll('.pi').forEach((p) => p.classList.toggle('hi', v[p.dataset.n] === 1));
  if (state.mod === 'alu') {
    const y = [0, 1, 2, 3].reduce((s, i) => s + (v[`y${i}`] << i), 0);
    const op = vin.f1 ? (vin.sub ? 'sub' : 'add') : vin.f0 ? 'or' : 'and';
    const a = [0, 1, 2, 3].reduce((s, i) => s + (vin[`a${i}`] << i), 0), b = [0, 1, 2, 3].reduce((s, i) => s + (vin[`b${i}`] << i), 0);
    const c = state.follow && !atEnd() ? coreAlu() : null;
    $('#socAluOut').textContent = `${a} ${{ add: '+', sub: '−', and: 'AND', or: 'OR' }[op]} ${b} → y = ${y} (0b${y.toString(2).padStart(4, '0')}), cout = ${v.cout}, zero = ${v.zero}` + (c ? ` · from the core: ${c.why}, low 4 bits` : '');
  }
}

function renderAluIn() {
  const box = $('#socAluIn');
  box.hidden = state.mod !== 'alu';
  if (box.hidden) return;
  const { a, b, op } = state.alu;
  box.innerHTML = `<label>a <input type="range" min="0" max="15" value="${a}" data-k="a" aria-label="Input a, 0 to 15"><output>${a}</output></label>` +
    `<label>b <input type="range" min="0" max="15" value="${b}" data-k="b" aria-label="Input b, 0 to 15"><output>${b}</output></label>` +
    `<div class="seg sm">${['and', 'or', 'add', 'sub'].map((o) => `<button type="button" data-op="${o}" aria-pressed="${op === o}">${o.toUpperCase()}</button>`).join('')}</div>` +
    `<label class="chk"><input type="checkbox" ${state.follow ? 'checked' : ''} data-k="follow"> Follow the running core</label><p class="small" id="socAluOut" aria-live="polite"></p>`;
  box.querySelectorAll('input[type=range]').forEach((r) => r.addEventListener('input', () => { state.alu[r.dataset.k] = +r.value; r.nextElementSibling.textContent = r.value; state.follow = false; box.querySelector('[data-k=follow]').checked = false; renderLive(); }));
  box.querySelectorAll('[data-op]').forEach((bt) => bt.addEventListener('click', () => { state.alu.op = bt.dataset.op; state.follow = false; renderAluIn(); }));
  box.querySelector('[data-k=follow]').addEventListener('change', (e) => { state.follow = e.target.checked; renderLive(); });
}

// ------------------------------------------------------------------ layout view
function renderLayout() {
  const L = mod().layout[state.tech];
  const svg = $('#socLayout');
  const pad = L.row_h * 0.06, W = L.width + 2 * pad, H = L.height + 2 * pad;
  svg.setAttribute('viewBox', `${-pad} ${-pad} ${W} ${H}`);
  const pxw = Math.max(640, Math.min(1600, mod().netlist.cells.length * 22));
  svg.setAttribute('width', pxw); svg.setAttribute('height', Math.round(pxw * H / W));
  const LY = SOCCELLS.layers;
  const order = ['nwell', 'pselect', 'nselect', 'active', 'fin', 'poly', 'metal1', 'contact', 'via', 'metal2'];
  let h = '';
  for (let r = 0; r < L.rows; r++) h += `<rect class="row" x="0" y="${r * L.row_h}" width="${L.width}" height="${L.row_h}"/>`;
  for (const p of L.place) {
    const c = SOCCELLS.gates[p.cell].cells[state.tech];
    const y0 = p.row * L.row_h;
    const tf = p.flip ? `translate(${p.x},${y0})` : `translate(${p.x},${y0 + L.row_h}) scale(1,-1)`;
    const shapes = [...c.shapes].sort((a, b) => order.indexOf(a[0]) - order.indexOf(b[0]))
      .map(([ly, x0, y1, x1, y2]) => `<rect x="${x0}" y="${y1}" width="${x1 - x0}" height="${y2 - y1}" fill="${LY[ly].colour}" fill-opacity="${LY[ly].opacity}"/>`).join('');
    h += `<g class="lc" data-id="${p.id}" transform="${tf}"><title>${CELLNAME[p.cell]} ${p.id}</title>${shapes}<rect class="lo" x="0" y="0" width="${c.w}" height="${c.h}"/></g>`;
  }
  svg.innerHTML = h;
  const um = (v) => (L.units === 'nm' ? v / 1000 : v);
  const area = um(L.width) * um(L.height);
  $('#socLayMeta').textContent = `${TECHLABEL[state.tech]} · ${L.rows} rows · ${um(L.width).toFixed(2)} × ${um(L.height).toFixed(2)} µm = ${area < 10 ? area.toFixed(2) : area.toFixed(0)} µm²`;
  const used = new Set(SOCCELLS.gates[mod().netlist.cells[0].cell].cells[state.tech].shapes.map((s) => s[0]));
  mod().netlist.cells.forEach((g) => SOCCELLS.gates[g.cell].cells[state.tech].shapes.forEach((s) => used.add(s[0])));
  $('#socLayKey').innerHTML = order.filter((k) => used.has(k)).map((k) => `<span><i style="background:${LY[k].colour}"></i>${k}</span>`).join('') +
    ' <span class="small">Rows alternate up and down so neighbours share a supply rail. Wiring between cells is not routed.</span>';
  applySel();
}

// ------------------------------------------------------------------ state machine
const SP = { FETCH: [90, 60], DECODE: [330, 60], EXEC_R: [50, 175], EXEC_I: [145, 175], MEMADR: [245, 175], BRANCH: [345, 175], JAL: [445, 175], LUI: [545, 175],
  ALUWB: [97, 290], MEMRD: [215, 290], MEMWR: [315, 290], MEMWB: [215, 385] };
const R0 = 30;
function renderFsm() {
  const svg = $('#socFsm');
  let h = '<defs><marker id="fsmArr" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L8,4 L0,8 z"/></marker></defs>';
  for (const [a, cond, b] of SOC.transitions) {
    const e = `${a}>${cond || ''}>${b}`;
    const [x1, y1] = SP[a];
    let d, lx, ly;
    if (b === 'FETCH' && a !== 'FETCH') {             // a short stub: "back to FETCH"
      d = `M${x1},${y1 + R0} L${x1},${y1 + R0 + 26}`;
      lx = x1; ly = y1 + R0 + 38;
      h += `<g class="ed back" data-e="${e}" tabindex="0" role="button" aria-label="${a} to FETCH"><path class="hit" d="${d}"/><path d="${d}" marker-end="url(#fsmArr)"/><text x="${lx}" y="${ly}" text-anchor="middle">↺ FETCH</text></g>`;
      continue;
    }
    const [x2, y2] = SP[b];
    const dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy);
    const sx = x1 + dx / L * R0, sy = y1 + dy / L * R0, ex = x2 - dx / L * (R0 + 2), ey = y2 - dy / L * (R0 + 2);
    d = `M${sx},${sy} L${ex},${ey}`;
    lx = sx + (ex - sx) * (cond ? 0.62 : 0.5); ly = sy + (ey - sy) * (cond ? 0.62 : 0.5) - 4;
    h += `<g class="ed" data-e="${e}" tabindex="0" role="button" aria-label="${a} to ${b}${cond ? ' when ' + cond : ''}"><path class="hit" d="${d}"/><path d="${d}" marker-end="url(#fsmArr)"/>${cond ? `<text x="${lx}" y="${ly}" text-anchor="middle">${cond}</text>` : ''}</g>`;
  }
  for (const s of SOC.states) {
    const [x, y] = SP[s];
    const code = SOC.states.indexOf(s).toString(2).padStart(4, '0');
    h += `<g class="st" data-s="${s}" tabindex="0" role="button" aria-label="State ${s}, code ${code}"><circle cx="${x}" cy="${y}" r="${R0}"/><text x="${x}" y="${y + 1}" text-anchor="middle">${s.replace('_', ' ')}</text><text class="code" x="${x}" y="${y + 14}" text-anchor="middle">${code}</text></g>`;
  }
  h += '<text class="fsm-note" x="630" y="460" text-anchor="end">Arrows are viewing points: click one</text>';
  svg.innerHTML = h;
}
function renderFsmLive() {
  const t = atEnd() ? null : cyc();
  document.querySelectorAll('#socFsm .st').forEach((el) => el.classList.toggle('now', !!t && el.dataset.s === t.state));
  document.querySelectorAll('#socFsm .ed').forEach((el) => {
    let on = false;
    if (t && state.cur + 1 < state.trace.length) on = el.dataset.e.startsWith(t.state + '>') && el.dataset.e.endsWith('>' + state.trace[state.cur + 1].state);
    el.classList.toggle('now', on);
  });
}

// ------------------------------------------------------------------ synthesis steps
const STEPS = ['RTL', 'Logic equations', 'Map to cells', 'Check', 'Place', 'Timing'];
function renderSteps() {
  $('#socSteps').innerHTML = STEPS.map((s, i) => `<button type="button" data-i="${i}" aria-pressed="${state.step === i}"><span class="n">${i + 1}</span>${s}</button>`).join('');
  const m = mod(), nl = m.netlist, st = m.stats, isC = state.mod === 'ctrl';
  const name = isC ? 'the controller' : 'the 4-bit ALU slice';
  let b = '';
  if (state.step === 0) {
    b = `<p>${isC ? 'The controller is written as two <code>case</code> statements: one gives the next state from the current state and the instruction class, the other gives the six write signals from the state alone (a Moore machine).' : 'The ALU slice is written as behaviour: an add with an optional inverted b, and a choice of AND, OR or the sum.'} The designer never draws a gate.</p>
      <p>${nl.inputs.length} inputs (${nl.inputs.join(', ')}) · ${nl.outputs.length} outputs (${nl.outputs.join(', ')}) · ${m.rtl.length} lines of Verilog.</p>`;
  } else if (state.step === 1) {
    b = `<p>${isC ? 'Each output’s truth table is minimised with the Quine–McCluskey method into a sum of products. Unused state codes (12–15), the unused class code 7 and impossible pairs are “don’t cares”, which lets terms grow larger and simpler.' : 'Each bit of the result, written as Boolean equations. The carry is the majority function: the carry-out is 1 when a and b are both 1, or when one of them and the carry-in are.'}</p>
      <table class="soc-eq">${Object.entries(m.equations).map(([k, v]) => `<tr><th scope="row">${esc(k)}</th><td>= ${v.map(esc).join(' <b>+</b> ')}</td></tr>`).join('')}</table>`;
  } else if (state.step === 2) {
    b = `<p>Technology mapping turns ANDs and ORs into the cells the library actually has. CMOS gates invert, so a two-level sum of products becomes NAND–NAND, with NOR and inverters where polarity needs it. ${isC ? 'Product terms shared by several outputs are built once.' : 'The result multiplexer uses AOI22 (AND-OR-invert) cells, two per bit.'}</p>
      <table class="soc-eq"><tr><th scope="col">Cell</th><th scope="col">Count</th><th scope="col">Transistors each</th></tr>${Object.entries(st.by_cell).map(([k, v]) => `<tr><td>${CELLNAME[k]}</td><td>${v}</td><td>${SOC.effort[k].n}</td></tr>`).join('')}<tr><th scope="row">Total</th><td>${st.cells}</td><td>${st.transistors}</td></tr></table>
      <p class="small">Transistor counts are the cells’ own, from the Gate to silicon bench (the XOR2 includes its two input inverters).</p>`;
  } else if (state.step === 3) {
    const n = isC ? '79 legal (state, class) pairs' : 'all 2,048 combinations of a, b, sub, f1 and f0';
    b = `<p>Before anything is placed, the gate netlist is simulated against the RTL’s behaviour for ${n}. Any difference fails the build (<code>tests/test_soc.py</code>). Real flows do the same with formal equivalence checking, which proves the match without listing every input.</p>`;
  } else if (state.step === 4) {
    const rows = Object.keys(SOC.techs).map((t) => {
      const L = m.layout[t], um = (v) => v / 1000, a = um(L.width) * um(L.height);
      return [t, L, a];
    });
    const a0 = rows[0][2];
    b = `<p>The placer puts the cells in rows of equal height with supply rails top and bottom, in netlist order, flipping every other row. The same ${st.cells} cells take this much silicon in each technology:</p>
      <table class="soc-eq"><tr><th scope="col">Technology</th><th scope="col">Rows</th><th scope="col">Block</th><th scope="col">Area</th><th scope="col">vs 180 nm</th></tr>${rows.map(([t, L, a]) => `<tr><td>${TECHLABEL[t]}</td><td>${L.rows}</td><td>${(L.width / 1000).toFixed(2)} × ${(L.height / 1000).toFixed(2)} µm</td><td>${a.toFixed(a < 10 ? 2 : 0)} µm²</td><td>${(a0 / a).toFixed(0)}× smaller</td></tr>`).join('')}</table>
      <p class="small">Cell widths and heights come from data/gate_cells.json: λ rules for 180 nm, a gate pitch of 51 nm for the FinFET cells (yeap2019) and estimated pitches for the nanosheet.</p>`;
  } else {
    const t = RV.sta(nl, SOC.effort);
    const G = gateById();
    b = `<p>Static timing analysis adds up delays along every path and reports the slowest. With logical effort, a cell’s delay is <i>d</i> = <i>p</i> + <i>C</i><sub>load</sub>, in units of τ: its parasitic delay plus the input capacitance it drives (the sum of the logical efforts of the pins on its output, or 4 for a block output). One fan-out-of-4 inverter delay (FO4) is 5 τ.</p>
      <p><b>Critical path of ${name}: ${t.tau.toFixed(1)} τ ≈ ${t.fo4.toFixed(1)} FO4</b>, through ${t.path.length} cells to <code>${t.end}</code>. ${isC ? 'It runs from a state bit, through its inverter and a product term, into the OR tree of a next-state bit.' : 'It is the carry rippling from bit 0 to bit 3, then the zero detector: the reason real ALUs use carry-lookahead or prefix adders.'}</p>
      <ol class="soc-path">${t.path.map((id) => `<li><button type="button" data-g="${id}">${CELLNAME[G[id].cell]} ${id}</button> +${t.delay[id].toFixed(2)} τ</li>`).join('')}</ol>
      <p class="small">Turn on “Critical path” above to see it in the schematic and the layout.</p>`;
  }
  $('#socStepBody').innerHTML = b;
  $('#socStepBody').querySelectorAll('[data-g]').forEach((bt) => bt.addEventListener('click', () => { select({ k: 'gate', id: bt.dataset.g }); $('#views').scrollIntoView({ behavior: reduce() ? 'auto' : 'smooth' }); }));
}

// ------------------------------------------------------------------ pipeline
function renderPipeline() {
  let pl, mc = state.final;
  try { pl = RV.pipeline(state.words); } catch (e) { $('#socPipe').textContent = e.message; return; }
  $('#socPStats').innerHTML = [
    ['Multi-cycle', `${mc.cycles} cycles`, `${mc.cpi.toFixed(2)} cycles per instruction`],
    ['Five-stage pipeline', `${pl.cycles} cycles`, `${pl.cpi.toFixed(2)} cycles per instruction`],
    ['Load-use stalls', String(pl.stalls), 'one bubble each'],
    ['Flushed fetches', String(pl.flushes), 'two per taken branch or jump'],
  ].map(([a, b, c]) => `<div class="card soc-tile"><span>${a}</span><b>${b}</b><small>${c}</small></div>`).join('');
  const N = pl.cycles;
  const rows = [];
  pl.rows.forEach((r) => {
    rows.push({ label: r.text, cells: { [r.if]: 'IF', [r.id]: 'ID', ...(r.stall ? { [r.id + 1]: '·' } : {}), [r.ex]: 'EX', [r.mem]: 'MEM', [r.wb]: 'WB' } });
    r.flushed.forEach((t) => rows.push({ label: 'wrong-path fetch (flushed)', ghost: true, cells: { [t]: 'IF', ...(t + 1 < r.ex + 1 ? { [t + 1]: 'ID' } : {}) } }));
  });
  const head = `<div class="pr hd" role="row"><span class="pl" role="columnheader">Instruction</span>${Array.from({ length: N }, (_, i) => `<span class="pc" role="columnheader">${i}</span>`).join('')}</div>`;
  $('#socPipe').style.setProperty('--n', N);
  $('#socPipe').innerHTML = head + rows.map((r) => `<div class="pr${r.ghost ? ' ghost' : ''}" role="row"><span class="pl" role="rowheader">${esc(r.label)}</span>${Array.from({ length: N }, (_, i) => { const s = r.cells[i]; return `<span class="pc${s ? ' s-' + (s === '·' ? 'stall' : s.toLowerCase()) : ''}" role="cell">${s || ''}</span>`; }).join('')}</div>`).join('');
}

// ------------------------------------------------------------------ x86
const X86PRE = [
  ['Sum loop', SOC.x86_demo],
  ['Memory add', 'BB F8 00 00 00 B8 07 00 00 00 01 43 08 03 43 08 EB FE'],
  ['Stack', 'B8 2A 00 00 00 BC 00 02 00 00 50 59 EB FE'],
  ['Compare', 'B8 03 00 00 00 B9 03 00 00 00 39 C8 74 02 41 41 42 EB FE'],
];
function renderX86() {
  const src = $('#x86Src').value;
  const err = $('#x86Err'); err.textContent = '';
  let tx;
  try { tx = RV.x86Translate(src); } catch (e) { err.textContent = e.message; return; }
  $('#x86Table tbody').innerHTML = tx.ins.map((o) => `<tr><td>${o.at}</td><td><code>${o.bytes.map((b) => b.toString(16).toUpperCase().padStart(2, '0')).join(' ')}</code><small>${o.len} byte${o.len > 1 ? 's' : ''}</small></td>` +
    `<td><code>${esc(o.text)}</code></td><td>${o.uops.map(esc).join('<br>')}${o.fused ? '<br><small class="fz">fuses with the next jump</small>' : ''}</td><td><code>${o.rv.length ? o.rv.map(esc).join('<br>') : '—'}</code>${!o.rv.length && o.fused ? '<br><small>folded into the branch</small>' : ''}</td></tr>`).join('');
  $('#x86Stats').innerHTML = `<div class="soc-tile"><span>x86 code</span><b>${tx.x86_bytes} bytes</b><small>${tx.ins.length} instructions, ${Math.min(...tx.ins.map((o) => o.len))}–${Math.max(...tx.ins.map((o) => o.len))} bytes each</small></div>` +
    `<div class="soc-tile"><span>µops</span><b>${tx.uop_count}</b><small>after compare-and-branch fusion</small></div>` +
    `<div class="soc-tile"><span>RV32I</span><b>${tx.rv_count * 4} bytes</b><small>${tx.rv_count} instructions, 4 bytes each</small></div>`;
  try {
    const w = RV.assemble(tx.asm).words, r = RV.sequential(w, 5000);
    const halted = r.seq.length < 5000;
    const regs = RV.X86_REGS.map((n) => `<span><b>${n}</b>${r.x[RV.X86_MAP[n]] | 0}</span>`).join('');
    const mem = Object.entries(r.mem).map(([k, v]) => `[${hex(+k, 3)}] = ${v | 0}`).join(' · ');
    $('#x86Run').innerHTML = `<h4>Run on the RISC-V core</h4><p class="small">${halted ? `${r.seq.length} RISC-V instructions executed.` : 'Still running after 5,000 instructions: end the code with EB FE (jump to itself).'} The x86 registers, read from their RISC-V homes:</p><div class="soc-regs x86">${regs}</div>${mem ? `<p class="small">Memory written: ${mem}</p>` : ''}`;
  } catch (e) { $('#x86Run').innerHTML = `<p class="small soc-err">${esc(e.message)}</p>`; }
}

// ------------------------------------------------------------------ wiring
function setMod(m) {
  state.mod = m; store.set('soc:mod', m); state.sel = null; state.rtl = 'mod';
  document.querySelectorAll('#socMod button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.v === m)));
  renderRtl(); renderGates(); renderLayout(); renderSteps(); applySel();
}

function delegate(root, sel, fn) {
  root.addEventListener('click', (e) => { const el = e.target.closest(sel); if (el && root.contains(el)) fn(el); });
  root.addEventListener('keydown', (e) => { if (e.key !== 'Enter' && e.key !== ' ') return; const el = e.target.closest(sel); if (el && root.contains(el)) { e.preventDefault(); fn(el); } });
}

function init() {
  assembleAndReset(SOC.demo);
  $('#socSrc').value = SOC.demo;
  drawChip(); renderList(); renderFsm();
  $('#socTech').innerHTML = Object.keys(SOC.techs).map((t) => `<button type="button" data-v="${t}" aria-pressed="${state.tech === t}">${TECHLABEL[t]}</button>`).join('');
  setMod(state.mod);
  renderChip(); renderPipeline();
  $('#socStep').addEventListener('click', () => { run(false); stepCycle(); });
  $('#socStepI').addEventListener('click', () => { run(false); stepInstr(); });
  $('#socRun').addEventListener('click', () => { if (atEnd()) state.cur = 0; run(!state.timer); });
  $('#socReset').addEventListener('click', () => { run(false); state.cur = 0; renderChip(); });
  $('#socAsm').addEventListener('click', () => {
    run(false);
    try { assembleAndReset($('#socSrc').value); $('#socErr').textContent = ''; renderList(); renderChip(); renderPipeline(); } catch (e) { $('#socErr').textContent = e.message; }
  });
  $('#socDemo').addEventListener('click', () => { $('#socSrc').value = SOC.demo; $('#socAsm').click(); });
  delegate($('#socMod'), 'button', (b) => setMod(b.dataset.v));
  delegate($('#socTech'), 'button', (b) => {
    state.tech = b.dataset.v; store.set('soc:tech', state.tech);
    document.querySelectorAll('#socTech button').forEach((x) => x.setAttribute('aria-pressed', String(x === b)));
    renderLayout();
  });
  $('#socCrit').addEventListener('click', (e) => { state.crit = !state.crit; e.currentTarget.setAttribute('aria-pressed', String(state.crit)); applySel(); });
  $('#socLive').addEventListener('click', (e) => { state.live = !state.live; e.currentTarget.setAttribute('aria-pressed', String(state.live)); renderLive(); });
  $('#socClear').addEventListener('click', () => select(null));
  delegate($('#socRtlTab'), 'button', (b) => { state.rtl = b.dataset.v; state.sel = null; renderRtl(); applySel(); });
  delegate($('#socRtl'), '.ln.tg', (el) => select({ k: 'line', i: +el.dataset.i }));
  delegate($('#socGates'), '.g', (el) => select({ k: 'gate', id: el.dataset.id }));
  $('#socGates').addEventListener('click', (e) => { const p = e.target.closest('.w'); if (p) select({ k: 'net', n: p.dataset.n }); });
  $('#socLayout').addEventListener('click', (e) => { const el = e.target.closest('.lc'); if (el) select({ k: 'gate', id: el.dataset.id }); });
  delegate($('#socFsm'), '.st', (el) => select({ k: 'state', s: el.dataset.s }));
  delegate($('#socFsm'), '.ed', (el) => select({ k: 'edge', e: el.dataset.e }));
  delegate($('#socSteps'), 'button', (b) => { state.step = +b.dataset.i; renderSteps(); });
  document.querySelectorAll('.soc-ladder [data-go]').forEach((a) => a.addEventListener('click', () => {
    const id = { rtl: 'vRtl', gates: 'vGates', layout: 'vLayout', fsm: 'vFsm' }[a.dataset.go];
    setTimeout(() => document.getElementById(id)?.classList.add('flash'), 300);
    setTimeout(() => document.getElementById(id)?.classList.remove('flash'), 1800);
  }));
  $('#x86Pre').innerHTML = X86PRE.map(([l], i) => `<button type="button" data-i="${i}" aria-pressed="${i === 0}">${l}</button>`).join('');
  $('#x86Src').value = X86PRE[0][1];
  delegate($('#x86Pre'), 'button', (b) => { $('#x86Src').value = X86PRE[+b.dataset.i][1]; document.querySelectorAll('#x86Pre button').forEach((x) => x.setAttribute('aria-pressed', String(x === b))); renderX86(); });
  $('#x86Go').addEventListener('click', renderX86);
  renderX86();
  $('#socRefs').innerHTML = Object.values(REFS).sort((a, b) => a.id.localeCompare(b.id)).map((r) => `<li id="ref-${r.id}">${esc(r.cite)} ${r.link ? `<a href="${r.link}" rel="noopener">${r.doi ? 'doi' : 'link'}</a>` : ''}</li>`).join('');
  // deep links for screenshots and sharing: ?mod=alu&tech=planar_180&sel=state:FETCH&cycle=12&crit=1&step=5
  const q = new URLSearchParams(location.search);
  if (q.get('mod')) setMod(q.get('mod') === 'alu' ? 'alu' : 'ctrl');
  if (q.get('tech') && SOC.techs[q.get('tech')]) document.querySelector(`#socTech [data-v="${q.get('tech')}"]`)?.click();
  if (q.get('cycle')) { state.cur = Math.min(+q.get('cycle'), state.trace.length); renderChip(); }
  if (q.get('crit') === '1') $('#socCrit').click();
  if (q.get('step')) { state.step = Math.max(0, Math.min(5, +q.get('step'))); renderSteps(); }
  const sl = q.get('sel');
  if (sl) {
    const [k, ...rest] = sl.split(':'), v = rest.join(':');
    select(k === 'state' ? { k, s: v } : k === 'edge' ? { k, e: v } : k === 'gate' ? { k, id: v } : k === 'line' ? { k, i: +v } : null);
  }
}

init();
